import{_ as s,o as a,c as r,a2 as i}from"./chunks/framework.ktMMbWgA.js";const v=JSON.parse('{"title":"第 33 讲 · 具身智能 — 物理世界的重锤 · 参考","description":"","frontmatter":{"title":"第 33 讲 · 具身智能 — 物理世界的重锤 · 参考","act":6,"kind":"refs","prev":{"text":"L32 · 生成式 AI 的版图","link":"/lectures/L32-generative-ai/references"},"next":{"text":"L34 · 安全、红队与可解释性","link":"/lectures/L34-safety/references"}},"headers":[],"relativePath":"lectures/L33-embodied-ai/references.md","filePath":"lectures/L33-embodied-ai/references.md","lastUpdated":null}'),l={name:"lectures/L33-embodied-ai/references.md"};function t(n,e,d,c,o,f){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="l33-references-embodied-ai-—-物理世界的重锤" tabindex="-1">L33 References: Embodied AI — 物理世界的重锤 <a class="header-anchor" href="#l33-references-embodied-ai-—-物理世界的重锤" aria-label="Permalink to &quot;L33 References: Embodied AI — 物理世界的重锤&quot;">​</a></h1><blockquote><p><strong>Lecture</strong>: 具身智能 — 物理世界的重锤 <strong>Course</strong>: Intelligence, Computed — From First Principles to Production AI Systems</p></blockquote><blockquote><p><strong>Last Verified</strong>: 2026-05-04 (links and citations checked; replace this when re-verifying)</p></blockquote><hr><section class="ref-card"><h2 class="ref-card-title" id="学术论文">1. 学术论文</h2><h3 class="ref-group" id="学术论文--moravec-悖论与具身认知">Moravec 悖论与具身认知</h3><ol class="ref-list"><li class="ref-item" id="ref-P1"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P1</span><a class="ref-title" href="https://www.hup.harvard.edu/catalog.php?isbn=9780674576186" target="_blank" rel="noopener">Mind Children: The Future of Robot and Human Intelligence</a></div><div class="ref-meta">Moravec, H. · 1988 · Harvard University Press</div><p class="ref-desc"><strong>核心参考。</strong> Moravec 悖论的原始出处。&quot;高级推理容易，低级感知运动难&quot;的经典表述。</p></div></li><li class="ref-item" id="ref-P2"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P2</span><a class="ref-title" href="https://mitpress.mit.edu/9780262162395/" target="_blank" rel="noopener">How the Body Shapes the Way We Think: A New View of Intelligence</a></div><div class="ref-meta">Pfeifer, R. &amp; Bongard, J. · 2006 · MIT Press</div><p class="ref-desc">具身认知的代表作。核心论点：智能不能脱离身体存在。讲稿&quot;认知翻转&quot;段的理论基础。</p></div></li><li class="ref-item" id="ref-P3"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P3</span><span class="ref-title">Intelligence without Representation</span></div><div class="ref-meta">Brooks, R.A. · 1991 · <em>Artificial Intelligence</em>, 47(1-3), 139-159</div><p class="ref-desc">&quot;行为主义机器人学&quot;宣言。Brooks 主张抛弃符号表示，直接用感知-行动回路构建智能。具身 AI 的学术起点之一。</p></div></li></ol><h3 class="ref-group" id="学术论文--rt-2-vla-vision-language-action">RT-2 / VLA（Vision-Language-Action）</h3><ol class="ref-list"><li class="ref-item" id="ref-P4"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P4</span><a class="ref-title" href="https://arxiv.org/abs/2307.15818" target="_blank" rel="noopener">RT-2: Vision-Language-Action Models Transfer Web Knowledge to Robotic Control</a></div><div class="ref-meta">Brohan, A. et al. (Google DeepMind) · 2023 · arXiv:2307.15818</div><p class="ref-desc"><strong>核心参考。</strong> 第一个真正的 VLA 模型——把机器人动作当 token，用 VLM 做端到端控制。证明 LLM 的语义泛化能力可以迁移到机器人领域。</p></div></li><li class="ref-item" id="ref-P5"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P5</span><a class="ref-title" href="https://arxiv.org/abs/2212.06817" target="_blank" rel="noopener">RT-1: Robotics Transformer for Real-World Control at Scale</a></div><div class="ref-meta">Brohan, A. et al. (Google) · 2023 · <em>RSS 2023</em></div><p class="ref-desc">RT-2 的前作。展示了 Transformer 在机器人控制中的可行性，13 个月、13 个机器人收集的 130k 条轨迹。</p></div></li><li class="ref-item" id="ref-P6"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P6</span><a class="ref-title" href="https://arxiv.org/abs/2310.08864" target="_blank" rel="noopener">Open X-Embodiment: Robotic Learning Datasets and RT-X Models</a></div><div class="ref-meta">Open X-Embodiment Collaboration · 2024 · <em>ICRA 2024</em></div><p class="ref-desc">跨机器人平台的统一数据集（100 万+ 轨迹、22 种机器人）。解决具身智能的数据稀缺问题的重要尝试。</p></div></li><li class="ref-item" id="ref-P7"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P7</span><a class="ref-title" href="https://arxiv.org/abs/2410.24164" target="_blank" rel="noopener">π₀: A Vision-Language-Action Flow Model for General Robot Control</a></div><div class="ref-meta">Black, K. et al. (Physical Intelligence) · 2024 · arXiv:2410.24164</div><p class="ref-desc">Physical Intelligence (π) 的旗舰模型。基于 flow matching 的 VLA，支持多种机器人平台的零样本控制。</p></div></li><li class="ref-item" id="ref-P7b"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P7b</span><a class="ref-title" href="https://arxiv.org/abs/2504.14530" target="_blank" rel="noopener">π₀.5: VLA + Knowledge Insulation for Generalist Robots</a></div><div class="ref-meta">Physical Intelligence · 2025 · arXiv:2504.14530</div><p class="ref-desc">π₀.5——2025 年 4 月发布的进化版，添加 knowledge insulation，提高染豛泛化。</p></div></li><li class="ref-item" id="ref-P7c"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P7c</span><a class="ref-title" href="https://arxiv.org/abs/2406.09246" target="_blank" rel="noopener">OpenVLA: An Open-Source Vision-Language-Action Model</a></div><div class="ref-meta">Kim, M. J. et al. · 2024 · arXiv:2406.09246</div><p class="ref-desc">OpenVLA——首个开源 VLA 模型，2024 年机器人学术界热门起点。</p></div></li><li class="ref-item" id="ref-P7d"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P7d</span><a class="ref-title" href="https://arxiv.org/abs/2502.19645" target="_blank" rel="noopener">OpenVLA-OFT: Optimized Fine-Tuning for VLA Models</a></div><div class="ref-meta">Kim, M. J. et al. · 2025 · arXiv:2502.19645</div><p class="ref-desc">OpenVLA 调优优化论文——2025 年 VLA 调优实践总结。</p></div></li></ol><h3 class="ref-group" id="学术论文--sim-to-real-迁移">Sim-to-Real 迁移</h3><ol class="ref-list"><li class="ref-item" id="ref-P8"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P8</span><a class="ref-title" href="https://arxiv.org/abs/1804.10332" target="_blank" rel="noopener">Sim-to-Real: Learning Agile Locomotion for Quadruped Robots</a></div><div class="ref-meta">Tan, J. et al. · 2018 · <em>RSS 2018</em></div><p class="ref-desc">Sim-to-Real 的经典成功案例——在模拟器中训练四足机器人行走，迁移到真实 Minitaur。</p></div></li><li class="ref-item" id="ref-P9"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P9</span><a class="ref-title" href="https://arxiv.org/abs/1910.07113" target="_blank" rel="noopener">Solving Rubik&#39;s Cube with a Robot Hand</a></div><div class="ref-meta">OpenAI et al. · 2019 · arXiv:1910.07113</div><p class="ref-desc">Domain Randomization 的巅峰之作——用极端随机化在模拟器中训练机械手解魔方，成功迁移到真实手。</p></div></li><li class="ref-item" id="ref-P10"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P10</span><a class="ref-title" href="https://arxiv.org/abs/1703.06907" target="_blank" rel="noopener">Domain Randomization for Transferring Deep Neural Networks from Simulation to the Real World</a></div><div class="ref-meta">Tobin, J. et al. · 2017 · <em>IROS 2017</em></div><p class="ref-desc">Domain Randomization 方法论的奠基论文。核心思想：让模拟器&quot;随机地不真实&quot;，迫使策略学习鲁棒表示。</p></div></li><li class="ref-item" id="ref-P11"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P11</span><a class="ref-title" href="https://arxiv.org/abs/1808.00177" target="_blank" rel="noopener">Learning Dexterous In-Hand Manipulation</a></div><div class="ref-meta">OpenAI et al. · 2018 · <em>IJRR</em>, 39(1), 3-20</div><p class="ref-desc">Dactyl——用 6144 个并行模拟环境训练灵巧手操作。讲稿 Sim-to-Real 段的核心案例。</p></div></li></ol><h3 class="ref-group" id="学术论文--世界模型">世界模型</h3><ol class="ref-list"><li class="ref-item" id="ref-P12"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P12</span><a class="ref-title" href="https://openreview.net/forum?id=BZ5a1r-kVsf" target="_blank" rel="noopener"><strong>A Path Towards Autonomous Machine Intelligence</strong> (V 0.9.2)</a></div><div class="ref-meta">LeCun, Y. · 2022 · OpenReview</div><p class="ref-desc"><strong>核心参考。</strong> LeCun 的 JEPA 框架——提出世界模型应在&quot;表示空间&quot;而非&quot;像素空间&quot;做预测。本讲 World Model 段的理论基石。</p></div></li><li class="ref-item" id="ref-P13"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P13</span><a class="ref-title" href="https://arxiv.org/abs/2301.04104" target="_blank" rel="noopener">Mastering Diverse Domains through World Models (DreamerV3)</a></div><div class="ref-meta">Hafner, D. et al. · 2023 · arXiv:2301.04104</div><p class="ref-desc">DreamerV3——能在&quot;梦境&quot;中学习的通用 RL Agent。Atari、机器人控制、Minecraft 统一框架。World Model 段核心案例。</p></div></li><li class="ref-item" id="ref-P14"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P14</span><a class="ref-title" href="https://arxiv.org/abs/2310.06114" target="_blank" rel="noopener">UniSim: Learning Interactive Real-World Simulators</a></div><div class="ref-meta">Yang, M. et al. (Google DeepMind) · 2023 · arXiv:2310.06114</div><p class="ref-desc">从视频数据学习&quot;通用模拟器&quot;——给定场景+动作，预测下一步。Learned physics simulator 的代表工作。</p></div></li><li class="ref-item" id="ref-P15"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P15</span><a class="ref-title" href="https://deepmind.google/discover/blog/genie-2-a-large-scale-foundation-world-model/" target="_blank" rel="noopener">Genie 2: A Large-Scale Foundation World Model</a></div><div class="ref-meta">Google DeepMind · 2024 · Blog post + Technical report</div><p class="ref-desc">从单张图片生成可交互 3D 环境。World Model 段的最新进展。</p></div></li><li class="ref-item" id="ref-P15b"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P15b</span><a class="ref-title" href="https://deepmind.google/discover/blog/genie-3-a-new-frontier-for-world-models/" target="_blank" rel="noopener">Genie 3: A New Frontier for World Models</a></div><div class="ref-meta">Google DeepMind · 2025 · Blog post</div><p class="ref-desc">Genie 3——2025 年发布，进化到多分钟交互 + 720p 实时生成。</p></div></li><li class="ref-item" id="ref-P15c"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P15c</span><a class="ref-title" href="https://developer.nvidia.com/isaac/gr00t" target="_blank" rel="noopener">NVIDIA GR00T: A Foundation Model for Humanoid Robots</a></div><div class="ref-meta">NVIDIA Research · 2025 · GR00T project</div></div></li><li class="ref-item" id="ref-P15d"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P15d</span><a class="ref-title" href="https://arxiv.org/abs/2501.03575" target="_blank" rel="noopener">Cosmos: A World Foundation Model Platform for Physical AI</a></div><div class="ref-meta">NVIDIA, 2025 · arXiv:2501.03575 · arXiv</div></div></li><li class="ref-item" id="ref-P16"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P16</span><a class="ref-title" href="https://arxiv.org/abs/1803.10122" target="_blank" rel="noopener">World Models</a></div><div class="ref-meta">Ha, D. &amp; Schmidhuber, J. · 2018 · arXiv:1803.10122</div><p class="ref-desc">&quot;World Model&quot; 这个术语在深度学习社区的奠基论文。用 VAE + RNN 学习环境的压缩表示，在&quot;梦境&quot;中训练策略。</p></div></li></ol><h3 class="ref-group" id="学术论文--figure-tesla-optimus-与人形机器人">Figure、Tesla Optimus 与人形机器人</h3><ol class="ref-list"><li class="ref-item" id="ref-P17"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P17</span><a class="ref-title" href="https://www.youtube.com/watch?v=Sq1QZB5baNw" target="_blank" rel="noopener"><strong>Figure Status Update</strong> (Figure 01 + OpenAI integration demo)</a></div><div class="ref-meta">Figure AI · 2024 · Company blog / YouTube</div><p class="ref-desc">Figure 01 与 OpenAI 多模态模型的厨房演示。讲稿&quot;Figure&quot;段的核心素材。</p></div></li><li class="ref-item" id="ref-P18"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P18</span><a class="ref-title" href="https://www.youtube.com/watch?v=cpraXaw7dyc" target="_blank" rel="noopener">Optimus Gen 2 Demo</a></div><div class="ref-meta">Tesla · 2024 · YouTube / Tesla AI Day</div><p class="ref-desc">Optimus Gen 2 的工厂分拣、鸡蛋处理等演示。讲稿&quot;Tesla Optimus&quot;段素材。注意区分自主 vs 遥操作。</p></div></li><li class="ref-item" id="ref-P19"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P19</span><span class="ref-title">Humanoid Robots: A Survey</span></div><div class="ref-meta">2024 · <em>IEEE Transactions on Robotics</em> (various survey articles)</div><p class="ref-desc">人形机器人技术综述——运动控制、感知、任务规划的系统梳理。背景阅读。</p></div></li></ol><h3 class="ref-group" id="学术论文--darpa-机器人挑战赛与基准">DARPA 机器人挑战赛与基准</h3><ol class="ref-list"><li class="ref-item" id="ref-P20"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P20</span><span class="ref-title">Lessons from the DARPA Robotics Challenge Finals</span></div><div class="ref-meta">Krotkov, E. et al. · 2017 · <em>IJRR</em>, 36(1), 3-29</div><p class="ref-desc">DRC 决赛的官方技术总结——23 个机器人的表现分析、失败模式分类。讲稿&quot;失败视频&quot;段的学术支撑。</p></div></li><li class="ref-item" id="ref-P21"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P21</span><a class="ref-title" href="https://arxiv.org/abs/2208.10552" target="_blank" rel="noopener">SpeedFolding: Learning Efficient Bimanual Folding of Garments</a></div><div class="ref-meta">Avigal, Y. et al. · 2023 · <em>Science Robotics</em>, 8(84)</div><p class="ref-desc">从 25 分钟到 2 分钟——衣物折叠速度的戏剧性进步。讲稿 Berkeley 毛巾案例的来源。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="书籍">2. 书籍</h2><ol class="ref-list"><li class="ref-item" id="ref-B1"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B1</span><span class="ref-title">Mind Children: The Future of Robot and Human Intelligence</span></div><div class="ref-meta">Moravec, H. · 1988 · Harvard University Press</div><p class="ref-desc">Moravec 悖论的原始出处。第 1-2 章详细论述&quot;为什么对计算机来说简单的对人难，反之亦然&quot;。</p></div></li><li class="ref-item" id="ref-B2"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B2</span><span class="ref-title">How the Body Shapes the Way We Think: A New View of Intelligence</span></div><div class="ref-meta">Pfeifer, R. &amp; Bongard, J. · 2006 · MIT Press</div><p class="ref-desc">具身认知的教科书级作品。&quot;智能不能脱离身体&quot;论点的系统论证。</p></div></li><li class="ref-item" id="ref-B3"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B3</span><span class="ref-title">Probabilistic Robotics</span></div><div class="ref-meta">Thrun, S., Burgard, W. &amp; Fox, D. · 2005 · MIT Press</div><p class="ref-desc">机器人状态估计、SLAM、不确定性处理的经典教材。理解 Sim-to-Real gap 中&quot;传感器噪声&quot;问题的基础。</p></div></li><li class="ref-item" id="ref-B4"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B4</span><span class="ref-title">Introduction to Autonomous Robots: Mechanisms, Sensors, Actuators, and Algorithms</span></div><div class="ref-meta">Correll, N., Hayes, B. &amp; Rother, C. · 2022 · MIT Press (open access)</div><p class="ref-desc">开源机器人学教材，覆盖运动学、传感器、控制。适合想深入技术细节的学员。</p></div></li><li class="ref-item" id="ref-B5"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B5</span><span class="ref-title">Robot Dreams</span></div><div class="ref-meta">Asimov, I. · 1986 · Ace Books</div><p class="ref-desc">非技术推荐——科幻短篇集。可用于课后延伸思考：&quot;机器人是否需要&#39;梦境&#39;来学习？&quot;</p></div></li><li class="ref-item" id="ref-B6"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B6</span><span class="ref-title">The Embodied Mind: Cognitive Science and Human Experience</span></div><div class="ref-meta">Varela, F.J., Thompson, E. &amp; Rosch, E. · 1991 (2016 rev.) · MIT Press</div><p class="ref-desc">具身认知的哲学根基。从现象学角度论证认知与身体的不可分割性。适合对哲学背景感兴趣的学员。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="视频">3. 视频</h2><ol class="ref-list"><li class="ref-item" id="ref-V1"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V1</span><a class="ref-title" href="https://www.youtube.com/watch?v=g0TaYhjpOfo" target="_blank" rel="noopener">DARPA Robotics Challenge: Robots Falling Down (Compilation)</a></div><div class="ref-meta">IEEE Spectrum · ~3 min</div><p class="ref-desc"><strong>开场 + 失败视频段必用。</strong> DRC 决赛机器人摔倒集锦。教学合理使用。</p></div></li><li class="ref-item" id="ref-V2"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V2</span><a class="ref-title" href="https://www.youtube.com/watch?v=-e1_QhJ1EhQ" target="_blank" rel="noopener">Atlas Gets a Grip (+ Behind the Scenes)</a></div><div class="ref-meta">Boston Dynamics · ~2 min</div><p class="ref-desc">Atlas 体操表演 + NG 集锦。展示&quot;完美表演背后的无数次失败&quot;。</p></div></li><li class="ref-item" id="ref-V3"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V3</span><a class="ref-title" href="https://www.youtube.com/watch?v=Sq1QZB5baNw" target="_blank" rel="noopener">Figure 01 + OpenAI Demo: Conversational Robot</a></div><div class="ref-meta">Figure AI · ~3 min</div><p class="ref-desc">Figure 01 厨房对话+操作演示。讲稿 Figure 段核心素材。</p></div></li><li class="ref-item" id="ref-V4"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V4</span><a class="ref-title" href="https://www.youtube.com/watch?v=cpraXaw7dyc" target="_blank" rel="noopener">Tesla Optimus Gen 2 Demo</a></div><div class="ref-meta">Tesla · ~2 min</div><p class="ref-desc">Optimus Gen 2 行走、分拣、鸡蛋处理。注意区分自主 vs 遥操作场景。</p></div></li><li class="ref-item" id="ref-V5"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V5</span><a class="ref-title" href="https://www.youtube.com/watch?v=XGQu_cVpJko" target="_blank" rel="noopener">RT-2: Google DeepMind Robotic Transformer 2 Demo</a></div><div class="ref-meta">Google DeepMind · ~2 min</div><p class="ref-desc">RT-2 语义泛化演示——执行训练集中未见过的指令。</p></div></li><li class="ref-item" id="ref-V6"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V6</span><a class="ref-title" href="https://deepmind.google/discover/blog/genie-2-a-large-scale-foundation-world-model/" target="_blank" rel="noopener">Genie 2: Generating Playable 3D Worlds from Images</a></div><div class="ref-meta">Google DeepMind · ~2 min</div><p class="ref-desc">Genie 2 从单张图片生成可交互世界的演示。World Model 段素材。</p></div></li><li class="ref-item" id="ref-V7"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V7</span><span class="ref-title">Moravec&#39;s Paradox Explained</span></div><div class="ref-meta">Two Minute Papers · ~5 min</div><p class="ref-desc">Moravec 悖论的通俗解释。可用作预习素材推荐给学员。</p></div></li><li class="ref-item" id="ref-V8"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V8</span><a class="ref-title" href="https://sites.google.com/view/speedfolding" target="_blank" rel="noopener">SpeedFolding: Robot Folding Garments</a></div><div class="ref-meta">Berkeley Autolab · ~2 min</div><p class="ref-desc">从 25 分钟到 2 分钟的衣物折叠进步。&quot;仍然比人慢 12 倍&quot;的对比。</p></div></li><li class="ref-item" id="ref-V9"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V9</span><span class="ref-title">Yann LeCun: Objective-Driven AI — Towards AI Systems That Can Learn, Remember, Reason, and Plan</span></div><div class="ref-meta">Meta AI / various · ~60 min</div><p class="ref-desc">LeCun 本人讲解 JEPA / World Model 框架。可提取 5 分钟片段用于 World Model 段。</p></div></li><li class="ref-item" id="ref-V10"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V10</span><a class="ref-title" href="https://www.youtube.com/watch?v=_T3epByuhYs" target="_blank" rel="noopener">Physical Intelligence π₀ Demo</a></div><div class="ref-meta">Physical Intelligence · ~3 min</div><p class="ref-desc">π₀ VLA 模型控制多种机器人执行多种任务。展示 VLA 范式的最新进展。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="博文与技术长文">4. 博文与技术长文</h2><ol class="ref-list"><li class="ref-item" id="ref-A1"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A1</span><a class="ref-title" href="https://deepmind.google/discover/blog/rt-2-new-model-translates-vision-and-language-into-action/" target="_blank" rel="noopener">RT-2: New Model Translates Vision and Language into Action</a></div><div class="ref-meta">Google DeepMind Blog</div><p class="ref-desc">RT-2 官方博客，比论文更易懂。推荐学员阅读。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">Date：</span>2023-07</p></div></li><li class="ref-item" id="ref-A2"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A2</span><a class="ref-title" href="https://deepmind.google/discover/blog/genie-2-a-large-scale-foundation-world-model/" target="_blank" rel="noopener">Genie 2: A Large-Scale Foundation World Model</a></div><div class="ref-meta">Google DeepMind Blog</div><p class="ref-desc">Genie 2 官方介绍。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">Date：</span>2024-12</p></div></li><li class="ref-item" id="ref-A3"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A3</span><a class="ref-title" href="http://www.incompleteideas.net/IncIdeas/BitterLesson.html" target="_blank" rel="noopener">The Bitter Lesson (applied to robotics)</a></div><div class="ref-meta">Sutton, R.</div><p class="ref-desc">Rich Sutton 的&quot;苦涩教训&quot;——通用方法+规模 &gt; 利用人类知识。在具身智能中被重新审视。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">Date：</span>2019</p></div></li><li class="ref-item" id="ref-A4"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A4</span><a class="ref-title" href="https://en.wikipedia.org/wiki/Moravec%27s_paradox" target="_blank" rel="noopener"><strong>Moravec&#39;s Paradox</strong> (Wikipedia)</a></div><div class="ref-meta">Wikipedia</div><p class="ref-desc">快速参考。包含多位学者的原始引用。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">Date：</span>—</p></div></li><li class="ref-item" id="ref-A5"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A5</span><span class="ref-title">Why Robots Can&#39;t Fold Laundry</span></div><div class="ref-meta">IEEE Spectrum</div><p class="ref-desc">关于柔性物体操作难题的科普文章。背景阅读。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">Date：</span>2024</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="代码仓库-simulation-platforms">5. 代码仓库 &amp; Simulation Platforms</h2><ol class="ref-list"><li class="ref-item" id="ref-C1"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C1</span><a class="ref-title" href="https://github.com/google-deepmind/open_x_embodiment" target="_blank" rel="noopener">Open X-Embodiment</a></div><p class="ref-desc">跨机器人平台统一数据集 + RT-X 模型代码。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">Organization：</span>Google DeepMind et al.</p></div></li><li class="ref-item" id="ref-C2"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C2</span><a class="ref-title" href="https://github.com/isaac-sim/IsaacLab" target="_blank" rel="noopener">Isaac Lab (formerly Orbit)</a></div><p class="ref-desc">GPU 加速的机器人仿真框架。Sim-to-Real 段的工具参考。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">Organization：</span>NVIDIA</p></div></li><li class="ref-item" id="ref-C3"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C3</span><a class="ref-title" href="https://github.com/google-deepmind/mujoco" target="_blank" rel="noopener">MuJoCo</a></div><p class="ref-desc">最流行的机器人物理引擎之一，2022 年开源。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">Organization：</span>Google DeepMind</p></div></li><li class="ref-item" id="ref-C4"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C4</span><a class="ref-title" href="https://github.com/danijar/dreamerv3" target="_blank" rel="noopener">DreamerV3</a></div><p class="ref-desc">World Model RL Agent 的开源实现。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">Organization：</span>Hafner et al.</p></div></li><li class="ref-item" id="ref-C5"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C5</span><a class="ref-title" href="https://github.com/huggingface/lerobot" target="_blank" rel="noopener">LeRobot</a></div><p class="ref-desc">Hugging Face 的开源机器人学习平台——模型、数据集、训练流程。具身 AI 民主化尝试。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">Organization：</span>Hugging Face</p></div></li><li class="ref-item" id="ref-C6"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C6</span><a class="ref-title" href="https://github.com/openvla/openvla" target="_blank" rel="noopener">OpenVLA</a></div><p class="ref-desc">OpenVLA 官方开源仓——2024 年首个完全开源的 VLA 模型。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">Organization：</span>Stanford / Princeton</p></div></li><li class="ref-item" id="ref-C7"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C7</span><a class="ref-title" href="https://github.com/NVIDIA/Isaac-GR00T" target="_blank" rel="noopener">NVIDIA Isaac GR00T</a></div><p class="ref-desc">NVIDIA Project GR00T 主机仓——2025 年重点推进。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">Organization：</span>NVIDIA</p></div></li><li class="ref-item" id="ref-C8"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C8</span><a class="ref-title" href="https://github.com/Genesis-Embodied-AI/Genesis" target="_blank" rel="noopener">Genesis</a></div><p class="ref-desc">Genesis——2024 年末发布的高验证调调机器人仿真平台，与 MuJoCo 并列。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">Organization：</span>Genesis-Embodied-AI</p></div></li><li class="ref-item" id="ref-C9"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C9</span><a class="ref-title" href="https://github.com/robocasa/robocasa" target="_blank" rel="noopener">RoboCasa</a></div><p class="ref-desc">家居场景仿真环境——2024 年发布，为人形机器人训练提供家广场景。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">Organization：</span>Stanford / NVIDIA</p></div></li><li class="ref-item" id="ref-C10"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">C10</span><a class="ref-title" href="https://github.com/eureka-research/Eureka" target="_blank" rel="noopener">Eureka (NVIDIA)</a></div><p class="ref-desc">LLM 设计机器人奖励函数的代表籼——LLM 与机器人学习的接口。</p><p class="ref-desc ref-desc--extra"><span class="ref-extra-label">Organization：</span>NVIDIA Research</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="推荐阅读分级">6. 推荐阅读分级</h2><h3 class="ref-group" id="推荐阅读分级--快速了解-课前-课后-30-分钟">🏃 快速了解（课前/课后 30 分钟）</h3><p class="ref-prose">- A1（RT-2 博客）+ A4（Moravec Wikipedia）+ V7（Two Minute Papers）</p><h3 class="ref-group" id="推荐阅读分级--认真阅读-周末-2-3-小时">📖 认真阅读（周末 2-3 小时）</h3><p class="ref-prose">- P4（RT-2 论文）+ P12（LeCun World Model）+ P9（魔方机械手）</p><h3 class="ref-group" id="推荐阅读分级--深度研究-一周以上">🎓 深度研究（一周以上）</h3><p class="ref-prose">- P6（Open X-Embodiment）+ P13（DreamerV3）+ B2（Pfeifer 具身认知）+ B3（Probabilistic Robotics）</p></section>',10)])])}const h=s(l,[["render",t]]);export{v as __pageData,h as default};
